def toMinimalInfix(post):
    prec = {'+': 1, '-': 1, '*': 2, '/': 2, '^': 3}
    stack = []
    for c in post:
        if c in prec:
            bs, bp = stack.pop()
            as_, ap = stack.pop()
            p = prec[c]
            right_assoc = (c == '^')
            if ap < p or (ap == p and right_assoc):
                as_ = "(" + as_ + ")"
            if bp < p or (bp == p and not right_assoc):
                bs = "(" + bs + ")"
            stack.append((as_ + c + bs, p))
        else:
            stack.append((c, 99))
    return stack[0][0]
